-- CRM AI Agent V1 synthetic dataset. DEVELOPMENT/DEMO ONLY. Never use in production.
-- Dataset: crm_ai_agent_v1; seed=42; analysis_as_of=2026-10-01T00:00:00
-- Generated offline. This file never creates users or departments and never deletes existing data.
USE crm_system;
SET NAMES utf8mb4;

-- PRE-CHECK: must return five fully matching enabled users/departments. STOP on any mismatch.
SELECT e.*, u.id AS actual_user_id, u.username AS actual_username, u.dept_id AS actual_dept_id,
       u.status AS user_status, u.deleted AS user_deleted, d.dept_code AS actual_dept_code,
       CASE WHEN ur.user_id IS NOT NULL THEN r.role_code END AS actual_role_code,
       CASE WHEN ur.user_id IS NOT NULL THEN r.data_scope END AS actual_data_scope
FROM (SELECT 2107447193143648258 AS user_id, 'sales_manager01' AS username, 'SALES_MANAGER' AS role_code, 2206070000000000001 AS dept_id, 'SALES_DEPT_01' AS dept_code UNION ALL
SELECT 2107447512812527618 AS user_id, 'sales_staff01' AS username, 'SALES_STAFF' AS role_code, 2206070000000000001 AS dept_id, 'SALES_DEPT_01' AS dept_code UNION ALL
SELECT 2107447685940813826 AS user_id, 'sales_staff02' AS username, 'SALES_STAFF' AS role_code, 2206070000000000001 AS dept_id, 'SALES_DEPT_01' AS dept_code UNION ALL
SELECT 2107682836507561985 AS user_id, 'sales_manager02' AS username, 'SALES_MANAGER' AS role_code, 2206070000000000002 AS dept_id, 'SALES_DEPT_02' AS dept_code UNION ALL
SELECT 2107683040359124993 AS user_id, 'sales_staff03' AS username, 'SALES_STAFF' AS role_code, 2206070000000000002 AS dept_id, 'SALES_DEPT_02' AS dept_code) e
LEFT JOIN sys_user u ON u.id=e.user_id AND u.username=e.username
LEFT JOIN sys_department d ON d.id=u.dept_id AND d.dept_code=e.dept_code AND d.status=1 AND d.deleted=0
LEFT JOIN sys_role r ON r.role_code=e.role_code AND r.status=1 AND r.deleted=0
LEFT JOIN sys_user_role ur ON ur.user_id=u.id AND ur.role_id=r.id
ORDER BY e.username;

-- Expected role scopes: SALES_MANAGER=DEPT, SALES_STAFF=SELF. STOP on mismatch.
SELECT role_code, data_scope, status, deleted FROM sys_role
WHERE role_code IN ('SALES_MANAGER', 'SALES_STAFF') ORDER BY role_code;

-- COLLISION CHECK: all counts must be zero before import. Duplicate imports also fail unique keys.
SELECT
 (SELECT COUNT(*) FROM customer WHERE id BETWEEN 2308100000000000001 AND 2308100000000000300 OR customer_no LIKE 'KH230810%') AS customer_collisions,
 (SELECT COUNT(*) FROM contact WHERE id BETWEEN 2308101000000000001 AND 2308101000000000450) AS contact_collisions,
 (SELECT COUNT(*) FROM follow_record WHERE id BETWEEN 2308102000000000001 AND 2308102000000001200) AS follow_collisions;

